/**
 * Parts copy: the signed-off rows of the graph's parts content, read from the file the app ships
 * (src/data/content/parts.json, generated by scripts/content-snapshot/build.mjs). No Cloud Function
 * serves it. A host checks its flow is complete (`flowReady`, src/lib/partsContent.ts) before showing it.
 */
import type { PartsContent } from '../data/partsContentTypes';

let cached: Promise<PartsContent> | null = null;

/** Fetched as its own chunk the first time it is needed, kept for the page's life; a failed fetch can be retried. */
export function getPartsContent(): Promise<PartsContent> {
  if (!cached) {
    cached = import('../data/content/parts.json').then((m) => m.default.content as unknown as PartsContent).catch((e) => {
      cached = null;
      throw e;
    });
  }
  return cached;
}
